def furthest_building(heights, bricks, ladders):
    n = len(heights)
    best = [0]

    def helper(i, bricks, ladders):
        best[0] = max(best[0], i)
        if i == n - 1:
            return
        diff = heights[i + 1] - heights[i]
        if diff <= 0:
            helper(i + 1, bricks, ladders)
            return
        if ladders > 0:
            helper(i + 1, bricks, ladders - 1)         # try using a ladder
        if bricks >= diff:
            helper(i + 1, bricks - diff, ladders)        # try using bricks

    helper(0, bricks, ladders)
    return best[0]

