import heapq

def furthest_building(heights, bricks, ladders):
    min_heap = []                                # climbs currently "holding" a ladder
    for i in range(len(heights) - 1):
        diff = heights[i + 1] - heights[i]
        if diff > 0:
            heapq.heappush(min_heap, diff)
            if len(min_heap) > ladders:
                bricks -= heapq.heappop(min_heap)   # pay bricks for the smallest ladder-assigned climb
                if bricks < 0:
                    return i                            # can't afford this climb
    return len(heights) - 1

