    static int furthestBuilding(int[] heights, int bricks, int ladders) {
        PriorityQueue<Integer> minHeap = new PriorityQueue<>();  // climbs currently holding a ladder
        for (int i = 0; i < heights.length - 1; i++) {
            int diff = heights[i + 1] - heights[i];
            if (diff > 0) {
                minHeap.offer(diff);
                if (minHeap.size() > ladders) {
                    bricks -= minHeap.poll();        // pay bricks for the smallest ladder-assigned climb
                    if (bricks < 0) return i;           // can't afford this climb
                }
            }
        }
        return heights.length - 1;
    }
}

